import { useState } from 'react';
import { api } from '../api';

export default function YodleeConnector({ onImportComplete }) {
  const [connecting, setConnecting] = useState(false);
  const [sessionId, setSessionId] = useState(null);
  const [accounts, setAccounts] = useState([]);
  const [holdings, setHoldings] = useState([]);
  const [loading, setLoading] = useState(false);
  const [importing, setImporting] = useState(false);
  const [status, setStatus] = useState('');

  const connectToYodlee = async () => {
    setConnecting(true);
    setStatus('Connecting to Yodlee...');
    try {
      const result = await api.yodleeConnect();
      setSessionId(result.sessionId);
      setStatus('Connected! Opening Yodlee account linking...');

      // Open Yodlee linking window
      window.open(result.loginUrl, 'yodlee-link', 'width=800,height=600');

      // Poll for accounts (in a real app, you'd use webhooks)
      setTimeout(() => checkAccounts(result.sessionId), 5000);
    } catch (err) {
      setStatus('Connection failed: ' + err.message);
    } finally {
      setConnecting(false);
    }
  };

  const checkAccounts = async (sid) => {
    setLoading(true);
    try {
      const result = await api.yodleeGetAccounts(sid);
      setAccounts(result.account || []);
      setStatus(`Found ${result.account?.length || 0} linked accounts`);
    } catch (err) {
      setStatus('Failed to get accounts: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  const loadHoldings = async () => {
    if (!sessionId) return;
    setLoading(true);
    setStatus('Loading holdings data...');
    try {
      const result = await api.yodleeGetHoldings(sessionId);
      setHoldings(result.holdings || []);
      setStatus(`Loaded ${result.count} holdings`);
    } catch (err) {
      setStatus('Failed to load holdings: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  const importHoldings = async () => {
    if (!sessionId) return;
    setImporting(true);
    setStatus('Importing holdings to WealthOS...');
    try {
      const result = await api.yodleeImportHoldings(sessionId, true); // true = clear existing
      setStatus(result.message);
      if (onImportComplete) onImportComplete();
    } catch (err) {
      setStatus('Import failed: ' + err.message);
    } finally {
      setImporting(false);
    }
  };

  return (
    <div style={{ padding: 20, border: '1px solid var(--border)', borderRadius: 8, margin: '20px 0' }}>
      <h3 style={{ marginTop: 0 }}>🔗 Yodlee Account Aggregation</h3>
      <p style={{ color: 'var(--muted)', fontSize: 14 }}>
        Connect your financial accounts to automatically import positions from banks, brokerages, and investment firms.
      </p>

      {!sessionId && (
        <button
          className="btn btn-primary"
          onClick={connectToYodlee}
          disabled={connecting}
          style={{ marginBottom: 16 }}
        >
          {connecting ? '🔗 Connecting...' : '🔗 Connect Financial Accounts'}
        </button>
      )}

      {sessionId && (
        <div style={{ marginBottom: 16 }}>
          <div style={{ display: 'flex', gap: 12, marginBottom: 12 }}>
            <button
              className="btn btn-outline btn-sm"
              onClick={() => checkAccounts(sessionId)}
              disabled={loading}
            >
              {loading ? '⟳' : '🔍'} Check Accounts
            </button>
            <button
              className="btn btn-outline btn-sm"
              onClick={loadHoldings}
              disabled={loading || accounts.length === 0}
            >
              {loading ? '⟳' : '📊'} Load Holdings
            </button>
            <button
              className="btn btn-primary btn-sm"
              onClick={importHoldings}
              disabled={importing || holdings.length === 0}
            >
              {importing ? '⟳ Importing...' : '💾 Import to WealthOS'}
            </button>
          </div>

          {accounts.length > 0 && (
            <div style={{ marginBottom: 12 }}>
              <h4>Linked Accounts ({accounts.length})</h4>
              <div style={{ maxHeight: 150, overflow: 'auto', fontSize: 13 }}>
                {accounts.map((acc, i) => (
                  <div key={i} style={{ padding: '4px 0', borderBottom: '1px solid var(--border)' }}>
                    <strong>{acc.providerName}</strong> - {acc.accountName} ({acc.accountType})
                  </div>
                ))}
              </div>
            </div>
          )}

          {holdings.length > 0 && (
            <div>
              <h4>Holdings Preview ({holdings.length})</h4>
              <div style={{ maxHeight: 200, overflow: 'auto', fontSize: 12 }}>
                {holdings.slice(0, 10).map((h, i) => (
                  <div key={i} style={{ display: 'flex', justifyContent: 'space-between', padding: '2px 0' }}>
                    <span>{h.ticker} - {h.name}</span>
                    <span>{h.shares} shares @ ${h.price} = ${h.value}</span>
                  </div>
                ))}
                {holdings.length > 10 && <div>... and {holdings.length - 10} more</div>}
              </div>
            </div>
          )}
        </div>
      )}

      {status && (
        <div style={{
          padding: '8px 12px',
          borderRadius: 4,
          fontSize: 13,
          background: status.includes('failed') || status.includes('Failed') ? '#fee' : '#efe',
          color: status.includes('failed') || status.includes('Failed') ? '#c33' : '#363',
          border: `1px solid ${status.includes('failed') || status.includes('Failed') ? '#fcc' : '#cfc'}`
        }}>
          {status}
        </div>
      )}

      <div style={{ marginTop: 16, fontSize: 12, color: 'var(--muted)' }}>
        <strong>Note:</strong> Yodlee integration requires API credentials from Envestnet Yodlee.
        Contact them at <a href="https://developer.yodlee.com" target="_blank" rel="noopener">developer.yodlee.com</a> for access.
      </div>
    </div>
  );
}